function button(text, href, style = 'primary') { return `<a class="button button-${style}" href="${href}">${text}${arrow}</a>`; }
function eyebrow(text, light = false) { return `<p class="eyebrow${light ? ' eyebrow-light' : ''}"><span></span>${text}</p>`; }
function header(active = '', pageClass = '') {
 const current = pageClass.match(/page-([\w-]+)/)?.[1];
 const navigation = [['Home','index.html','home'],['About us','about.html','about'],['Our work','projects.html','projects'],['Downloads','resources.html','resources']];
 const supplyLinks = [['Pump accessories & spares','pump-accessories.html','pump-accessories'],['Pipes','mining-industrial.html#pipes-hoses-fittings','industrial'],['Valves','mining-industrial.html#valves-actuators','industrial'],['Actuators','mining-industrial.html#valves-actuators','industrial'],['Lifting equipment & material handling','lifting-rigging.html','lifting']];
 const equipment = [['Models & parts sheet','interchangeable-models-parts.html','parts']];
 const serviceLinks = [['Turnkey Projects','turnkey-projects.html','turnkey'],['Supplies','mining-industrial.html','industrial'],['Conveyor Plant Design and Installation','conveyor-systems.html','conveyor'],['Construction Services','construction.html','construction'],['Agriculture','agriculture.html','agriculture']];
 const section = (label, items) => `<div class="nav-service-group"><span class="nav-group-label">${label}</span><ul>${items.map(([name, url, key]) => `<li><a href="${url}"${current === key ? ' class="active" aria-current="page"' : ''}>${name}${arrow}</a></li>`).join('')}</ul></div>`;
 const disclosure = `<details class="nav-services"><summary${active === 'services' ? ' class="active"' : ''}>Services <span class="chevron" aria-hidden="true">⌄</span></summary><div class="service-dropdown">${section('Services', serviceLinks)}${section('Supplies', supplyLinks)}${section('Equipment &amp; parts', equipment)}</div></details>`;
 const link = ([name,url,key]) => `<a href="${url}"${active === key ? ` class="active" aria-current="${key === 'projects' && current ? 'location' : 'page'}"` : ''}>${name}</a>`;
 return `<a class="skip-link" href="#main">Skip to content</a><div class="utility-bar"><div class="container utility-inner"><span>${pin}PHALABORWA, SOUTH AFRICA</span><a href="tel:+27150041433">${phone}015 004 1433</a></div></div><header class="site-header"><div class="container header-inner"><a class="brand" href="index.html"><img src="assets/cps-logo.png" alt="" width="110" height="55"><span>CLEMENT PROJECTS <span>SOLUTION (PTY) LTD</span></span></a><button class="menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="main-nav"><span></span><span></span></button><nav id="main-nav" aria-label="Main navigation">${navigation.slice(0,2).map(link).join('')}${disclosure}${navigation.slice(2).map(link).join('')}<a class="button button-small" href="contact.html"${active === 'contact' ? ' aria-current="page"' : ''}>Enquire${arrow}</a></nav></div></header>`;
}
