function capabilityCards(groups) { return `<div class="capability-grid">${groups.map(([title, description, list], index) => { const id = title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''); return `<article class="capability-card" id="${id}"><span class="capability-index">${String(index + 1).padStart(2, '0')}</span><h3>${title}</h3><p>${description}</p><ul>${list.map(item => `<li>${item}</li>`).join('')}</ul></article>`; }).join('')}</div>`; }
