const contact = `${pageIntro('Contact','Let’s get<br><em>to work.</em>','Tell us what you need. We’ll help you find the right place to start.')}<section class="section contact-section"><div class="container contact-grid"><aside class="contact-details">${eyebrow('START A CONVERSATION')}<h2>Good work starts<br>with a clear brief.</h2><p>Call our team, message us on WhatsApp or prepare an email enquiry using the form.</p><a class="contact-big" href="tel:+27150041433">015 004 1433${diagonal}</a><div class="contact-block"><h3>General enquiries</h3><a href="mailto:info@clementprojectssolution.co.za">info@clementprojectssolution.co.za</a></div><div class="contact-block"><h3>Sales</h3><a href="mailto:sales@clementprojectssolution.co.za">sales@clementprojectssolution.co.za</a></div><div class="contact-block"><h3>Human resources</h3><a href="mailto:hr@clementprojectssolution.co.za">hr@clementprojectssolution.co.za</a></div><div class="contact-block contact-whatsapp"><h3>WhatsApp</h3><a class="whatsapp-contact-link" href="${whatsapp.url}" target="_blank" rel="noopener noreferrer" aria-label="Chat with CPS on WhatsApp at 065 691 8895 (opens in a new tab)">${whatsapp.icon}<span>Chat on WhatsApp<small>065 691 8895</small></span>${diagonal}</a></div><div class="contact-block"><h3>Find us</h3><p>189 Mosemaneng, Mashishimale<br>Phalaborwa, 1390<br>South Africa</p><a class="text-link" href="https://www.google.com/maps/search/?api=1&query=189+Mosemaneng+Mashishimale+Phalaborwa+1390" target="_blank" rel="noopener noreferrer">Open in maps${diagonal}</a></div><div class="contact-block"><h3>Follow us</h3>${renderSocialLinks({ includeWhatsApp: false })}</div><div class="contact-prompt">Not sure which service to choose?<br>Choose <strong>General enquiry</strong> and describe what you have in mind.</div></aside><div class="enquiry-panel"><form id="enquiry-form"><div class="form-heading"><span class="small-label">YOUR NEXT STEP</span><h2>Tell us about your requirements.</h2><p>This form prepares an email draft for our team. You review and send it from your email app.</p></div><aside class="selected-accessory" id="selected-accessory" aria-label="Selected product" hidden><span class="small-label">YOUR SELECTED PRODUCT</span><strong id="selected-accessory-name"></strong><a class="text-link" href="#detail">Edit selection${arrow}</a></aside><div class="field"><label for="service">I’m interested in <span aria-hidden="true">*</span></label><select id="service" name="service" required><option value="">Choose a service</option>${[...services, ...engineeringServices].map(s=>`<option value="${s.id}">${s.title}</option>`).join('')}<option value="lifting">Lifting & Rigging</option><option value="documents">Company documents</option><option value="general">General enquiry</option></select></div><div class="form-row"><div class="field"><label for="name">Full name <span aria-hidden="true">*</span></label><input id="name" name="name" autocomplete="name" required maxlength="120" placeholder="Your name"></div><div class="field"><label for="company">Company <span class="optional">(optional)</span></label><input id="company" name="company" autocomplete="organization" maxlength="160" placeholder="Company or farm name"></div></div><div class="form-row"><div class="field"><label for="email">Email address <span aria-hidden="true">*</span></label><input id="email" name="email" type="email" autocomplete="email" required maxlength="200" placeholder="you@company.co.za"></div><div class="field"><label for="phone">Phone number <span class="optional">(optional)</span></label><input id="phone" name="phone" type="tel" autocomplete="tel" maxlength="40" placeholder="Your contact number"></div></div><div class="field"><label for="location">Project or service location <span aria-hidden="true">*</span></label><input id="location" name="location" required maxlength="200" placeholder="Town, site or farm location"></div><div class="field service-extra" hidden><label for="detail" id="detail-label">Additional details</label><input id="detail" name="detail" maxlength="300"><p class="field-help" id="detail-help"></p></div><div class="form-row industrial-enquiry-fields" hidden><div class="field"><label for="pump-model"><span id="equipment-model-label">Pump model</span> <span class="optional">(optional)</span></label><input id="pump-model" name="pump_model" maxlength="120" placeholder="e.g. 6/4D-AH" disabled></div><div class="field"><label for="quantity">Quantity <span class="optional">(optional)</span></label><input id="quantity" name="quantity" type="number" min="1" max="1000000" step="1" inputmode="numeric" placeholder="How many?" disabled></div></div><div class="field"><label for="message"><span id="message-label-text">How can we help?</span> <span id="message-required" aria-hidden="true">*</span><span class="optional" id="message-optional" hidden>(optional)</span></label><textarea id="message" name="message" rows="5" required maxlength="3000" placeholder="Describe what you need, the scope and your preferred dates."></textarea></div><p class="form-privacy">Your information stays in this browser until you choose to email it. <a href="privacy.html">Read our privacy information.</a></p><button class="button button-primary" type="submit"><span id="enquiry-submit-label">Prepare email enquiry</span>${arrow}</button><p class="field-help">Fields marked * are required.</p></form><div id="enquiry-result" class="enquiry-result" hidden role="region" aria-labelledby="enquiry-result-title" tabindex="-1"><span class="result-mark">${arrow}</span><span class="small-label">READY FOR YOUR REVIEW</span><h2 id="enquiry-result-title">Your enquiry is prepared.</h2><p>Review the draft below, then open it in your email app to send. Your enquiry has not been sent yet.</p><pre id="enquiry-preview"></pre><a id="email-draft" class="button button-primary" href="mailto:info@clementprojectssolution.co.za">Open email draft${diagonal}</a><div class="result-actions"><button class="text-link" id="copy-enquiry" type="button">Copy enquiry</button><button class="text-link" id="edit-enquiry" type="button">Edit details${arrow}</button></div><p id="copy-status" class="field-help" aria-live="polite"></p><p class="field-help">No email app configured? Copy your enquiry and send it to <span id="draft-recipient">info@clementprojectssolution.co.za</span>.</p></div></div></div></section>`;
